@@ -19,7 +24,20 @@ type Config struct {
 	DataDir string
 }

-func New(cfg Config) http.Handler {
+type App struct {
+	handler http.Handler
+	db      *sqlite.DB
+}
+
+func (a *App) ServeHTTP(w http.ResponseWriter, r *http.Request) {
+	a.handler.ServeHTTP(w, r)
+}
+
+func (a *App) Close() error {
+	return a.db.Close()
+}
+
+func New(cfg Config) *App {
 	db, err := sqlite.New(cfg.DataDir)
 	if err != nil {
 		panic(fmt.Sprintf("open store: %v", err))
@@ -28,13 +46,16 @@ func New(cfg Config) http.Handler {
 	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
 		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
 	})
+	mux.HandleFunc("POST /api/signup", func(w http.ResponseWriter, r *http.Request) {
+		handleSignup(w, r, db)
+	})
 	mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
 		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
 	})
 	mux.Handle("/app/", http.StripPrefix("/app", app()))
 	mux.Handle("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
 	var s store.Store = db
-	return withStore(withSession(s, mux), s)
+	return &App{handler: withStore(withSession(s, mux), s), db: db}
 }

 func withStore(h http.Handler, s store.Store) http.Handler {
@@ -46,8 +67,9 @@ func withStore(h http.Handler, s store.Store) http.Handler {

 type storeKey struct{}

-func StoreFromContext(ctx context.Context) store.Store {
-	return ctx.Value(storeKey{}).(store.Store)
+func StoreFromContext(ctx context.Context) (store.Store, bool) {
+	s, ok := ctx.Value(storeKey{}).(store.Store)
+	return s, ok
 }

 func withSession(s store.Store, h http.Handler) http.Handler {
@@ -58,7 +80,12 @@ func withSession(s store.Store, h http.Handler) http.Handler {
 			return
 		}
 		sess, err := s.GetSession(r.Context(), sid)
-		if err != nil || sess.ExpiresAt.Before(time.Now().UTC()) {
+		if err != nil {
+			log.Printf("get session %s: %v", sid, err)
+			http.Error(w, "internal error", http.StatusInternalServerError)
+			return
+		}
+		if sess.ExpiresAt.Before(time.Now().UTC()) {
 			h.ServeHTTP(w, r)
 			return
 		}
@@ -67,6 +94,44 @@ func withSession(s store.Store, h http.Handler) http.Handler {
 	})
 }

+func handleSignup(w http.ResponseWriter, r *http.Request, s store.Store) {
+	var req struct {
+		Email    string `json:"email"`
+		Password string `json:"password"`
+	}
+	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request"})
+		return
+	}
+	if req.Email == "" || len(req.Password) < 10 {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "email required, password at least 10 characters"})
+		return
+	}
+	hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	user, err := s.CreateUser(r.Context(), req.Email, string(hash))
+	if err != nil {
+		writeJSON(w, http.StatusConflict, map[string]string{"error": "email already registered"})
+		return
+	}
+	sess, err := s.CreateSession(r.Context(), user.ID)
+	if err != nil {
+		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
+		return
+	}
+	session.SetCookie(w, r, sess.ID)
+	writeJSON(w, http.StatusCreated, map[string]string{"id": user.ID, "email": user.Email})
+}
+
+func newRandomSlug() string {
+	b := make([]byte, 4)
+	_, _ = rand.Read(b)
+	return hex.EncodeToString(b)[:7]
+}
+
 func writeJSON(w http.ResponseWriter, status int, v any) {
 	w.Header().Set("Content-Type", "application/json")
 	w.WriteHeader(status)

